export const ejercicioPorId = Object.fromEntries(EJERCICIOS.map(e => [e.id, e]));

// Ejercicios de una familia ordenados por dificultad
export function familia(nombre) {
  return EJERCICIOS.filter(e => e.familia === nombre).sort((a, b) => a.paso - b.paso);
}

